// Текст помилки за правилом «що впало → чому → що зробити».
// Стектрейс — у вторинне поле, не в перший рядок.
const e = $input.first().json;
const wf = e.workflow?.name ?? 'невідомий workflow';
const node = e.execution?.lastNodeExecuted ?? '—';
const raw = String(e.execution?.error?.message ?? e.error?.message ?? 'без тексту');

const DICT = [
  { rx: /401|unauthorized/i, human: 'сервер відповів 401 — облікові дані користувача інтеграції недійсні', fix: 'Оновити пароль у credentials n8n і повторити запуск. Дані в цільовій системі не змінювались.' },
  { rx: /403|forbidden/i, human: 'сервер відповів 403 — у користувача немає прав на цей об’єкт', fix: 'Перевірити права користувача інтеграції в базі клієнта.' },
  { rx: /404|not found/i, human: 'об’єкт не знайдено', fix: 'Звірити назву об’єкта через $metadata — у різних конфігураціях 1С/BAS вона відрізняється.' },
  { rx: /429|rate limit/i, human: 'перевищено ліміт запитів до API', fix: 'Ретраї вже виконані. Якщо повторюється — знизити частоту розкладу.' },
  { rx: /ETIMEDOUT|timeout/i, human: 'сервер не відповів у відведений час', fix: 'Перевірити доступність сервера клієнта. Документ залишився в черзі, дубля не буде.' },
  { rx: /duplicate key|unique/i, human: 'запис із таким ключем уже існує', fix: 'Це спрацював захист від дубля. Дій не потрібно.' }
];
const hit = DICT.find(d => d.rx.test(raw));

return [{ json: {
  workflow: wf,
  node,
  human: 'Крок «' + node + '» у «' + wf + '»: ' + (hit ? hit.human : raw.slice(0, 200)),
  fix: hit ? hit.fix : 'Відкрити execution у n8n і подивитися вхід кроку.',
  raw: raw.slice(0, 1500),
  execution_url: e.execution?.url ?? null,
  severity: /401|403/.test(raw) ? 'credentials' : 'generic'
}}];

